"""Publish a minimal native run record from captured session-matched evidence."""
import json,sys
from pathlib import Path
case=sys.argv[1];b=Path('experiments/2026-09-06-workflow-v1/lev_native/lev--native')/case;p=Path('work/workflow-v1/lev-native')/case
cost=json.loads((b/'cost-evidence.json').read_text());submission=json.loads((p/'submission.json').read_text());done=json.loads((p/'completed-time.json').read_text())
assert abs(sum(cost['generation_costs_usd'])-cost['total_cost_usd'])<1e-8
r={'case_id':case,'requested_model':'lev/native','track':'lev_native','status':'completed','started_at':submission['started_at'],'observed_completed_at':done['observed_completed_at'],'elapsed_seconds':cost['elapsed_seconds'],'latency_basis':'Matched PostHog workflow trace; excludes setup and post-completion observation delay','returned_models':cost['models'],'agent_version':cost['agent_versions'][0],'estimated_inference_cost_usd':cost['total_cost_usd'],'cost_basis':'PostHog trace estimate using OpenRouter model rates; charged generation events summed, duplicate run-summary excluded','cost_scope':'Matched native chat inference only. Setup extraction/classification, OCR, storage, hosting, subscription and operator time excluded; product credits not converted to USD.','operator_semantic_corrections':0,'operator_generation_confirmations':0,'latest_workbook':'artifacts/underwriting.xlsx','latest_memo':'artifacts/memorandum.pdf','model_calls_including_retries':None,'tool_calls':None,'source_commit':'bc0ffcb','trace_evidence':cost,'input_delivery':'Five exact frozen files uploaded at deal setup and directly attached to a fresh deal-context chat; identical frozen brief.'}
(b/'result.json').write_text(json.dumps(r,indent=2)+'\n');print(case,r['elapsed_seconds'],r['estimated_inference_cost_usd'])
